// Parse response and group by practice
const items = $input.all();
let automations = [];

// Log the raw response for debugging
console.log('Raw response:', JSON.stringify(items));

// n8n returns each row from Supabase as a separate item
// So we need to extract the json from each item
if (items && items.length > 0) {
  // Check if the first item is already an automation object
  if (items[0].json && items[0].json.queue_id) {
    // Each item is an automation, collect them all
    automations = items.map(item => item.json);
  } else {
    // Try other formats just in case
    const response = items[0].json;

    if (Array.isArray(response)) {
      automations = response;
    } else if (response && typeof response === 'object') {
      // Log the response structure
      console.log('Response type:', typeof response);
      console.log('Response keys:', Object.keys(response));

      // Check various possible response formats
      if (Array.isArray(response.data)) {
        automations = response.data;
      } else if (Array.isArray(response.result)) {
        automations = response.result;
      }
    }
  }
}

console.log(`Found ${automations.length} pending automations`);

// If no automations, return empty
if (automations.length === 0) {
  return [{ json: { message: 'No pending automations found' } }];
}

// Map practice IDs to Gmail credential IDs
const practiceCredentialMap = {
  'ffed1160-00ec-4c4f-8810-913a24348d90': 'uA0l39VD4cMHN9cC', // NewCharm
  'onehealth_practice_id': 'HrTrOqI74H5m5dyg', // OneHealth - replace with actual practice ID
  // Add more practice mappings here as needed
};

// Group by practice
const practiceGroups = {};
automations.forEach(automation => {
  const practiceId = automation.practice_id;
  if (!practiceGroups[practiceId]) {
    practiceGroups[practiceId] = {
      practice_id: practiceId,
      practice_name: automation.practice_name || 'Unknown Practice',
      gmail_credential_id: practiceCredentialMap[practiceId] || null,
      automations: []
    };
  }
  practiceGroups[practiceId].automations.push(automation);
});

// Return groups
return Object.values(practiceGroups).map(group => ({ json: group }));

// Process NewCharm automations in parallel
const automations = $json.automations || [];

// Separate SMS and Email automations based on enabled flags
const smsAutomations = automations.filter(a => a.sms_enabled);
const emailAutomations = automations.filter(a => a.email_enabled);

console.log(`NewCharm: ${smsAutomations.length} SMS, ${emailAutomations.length} Email`);

// Create outputs for parallel processing
const outputs = [];

if (smsAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',
      type: 'SMS',
      automations: smsAutomations
    }
  });
}

if (emailAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',  
      type: 'EMAIL',
      automations: emailAutomations
    }
  });
}

// If no automations, return empty result
if (outputs.length === 0) {
  outputs.push({
    json: {
      practice_id: $json.practice_id,
      practice_name: $json.practice_name || 'NewCharm',
      type: 'NONE',
      automations: []
    }
  });
}

return outputs;

