// Process emails one by one
const emailAutomations = $json.automations || [];
return emailAutomations.map(automation => {
  // Extract recipient email from payload
  const recipientEmail = automation.payload?.patientEmail || 
                        automation.payload?.patient_email || 
                        automation.payload?.email || 
                        '';

  // Replace template variables
  const replacePlaceholders = (template, data) => {
    if (!template) return '';
    return template
      .replace(/{{patientName}}/g, data.patientName || data.patient_name || '')
      .replace(/{{practiceName}}/g, data.practiceName || data.practice_name || $json.practice_name || '')
      .replace(/{{practicePhone}}/g, data.practicePhone || data.practice_phone || automation.practice_phone || '')
      .replace(/{{practiceEmail}}/g, data.practiceEmail || data.practice_email || automation.practice_email || '');
  };

  const subject = replacePlaceholders(automation.email_subject, automation.payload);
  const body = replacePlaceholders(automation.email_body, automation.payload);

  return {
    json: {
      to: recipientEmail,
      subject: subject,
      body: body,
      automation_id: automation.queue_id,
      practice_id: $json.practice_id,
      practice_name: $json.practice_name
    }
  };
});

// Collect NewCharm results
const results = $input.all();
const successItems = [];

results.forEach(result => {
  if (result.json.automation_id) {
    // Email result from Gmail node
    successItems.push({
      id: result.json.automation_id,
      type: 'EMAIL',
      practice_id: result.json.practice_id,
      status: 'completed'
    });
  } else if (result.json.success && result.json.results) {
    // SMS batch result from centralized gateway
    result.json.results.forEach(smsResult => {
      if (smsResult.success) {
        successItems.push({
          id: smsResult.automation_id || smsResult.metadata?.queue_id,
          type: 'SMS',
          practice_id: result.json.practice_id || smsResult.practice_id,
          status: 'completed'
        });
      }
    });
  } else if (result.json.automations) {
    // Fallback for batch processing
    result.json.automations.forEach(automation => {
      successItems.push({
        id: automation.queue_id || automation.id,
        type: result.json.type || 'UNKNOWN',
        practice_id: result.json.practice_id,
        status: 'completed'
      });
    });
  }
});

return successItems.map(item => ({ json: item }));

// Process OneHealth automations in parallel
