      .replace(/{{practiceName}}/g, data.practiceName || data.practice_name || $json.practice_name || '')
      .replace(/{{practicePhone}}/g, data.practicePhone || data.practice_phone || automation.practice_phone || '')
      .replace(/{{practiceEmail}}/g, data.practiceEmail || data.practice_email || automation.practice_email || '');
  };

  const subject = replacePlaceholders(automation.email_subject, automation.payload);
  const body = replacePlaceholders(automation.email_body, automation.payload);

  return {
    json: {
      to: recipientEmail,
      subject: subject,
      body: body,
      automation_id: automation.queue_id,
      practice_id: $json.practice_id,
      practice_name: $json.practice_name
    }
  };
});

// Collect OneHealth results
const results = $input.all();
const successItems = [];

results.forEach(result => {
  if (result.json.automation_id) {
    // Email result from Gmail node
    successItems.push({
      id: result.json.automation_id,
      type: 'EMAIL',
      practice_id: result.json.practice_id,
      status: 'completed'
    });
  } else if (result.json.success && result.json.results) {
    // SMS batch result from centralized gateway
    result.json.results.forEach(smsResult => {
      if (smsResult.success) {
        successItems.push({
          id: smsResult.automation_id || smsResult.metadata?.queue_id,
          type: 'SMS',
          practice_id: result.json.practice_id || smsResult.practice_id,
          status: 'completed'
        });
      }
    });
  } else if (result.json.automations) {
    // Fallback for batch processing
    result.json.automations.forEach(automation => {
      successItems.push({
        id: automation.queue_id || automation.id,
        type: result.json.type || 'UNKNOWN',
        practice_id: result.json.practice_id,
        status: 'completed'
      });
    });
  }
});

return successItems.map(item => ({ json: item }));

// Handle unknown practices dynamically
const practiceData = $json;

console.log('Processing unknown practice:', {
  practice_id: practiceData.practice_id,
  practice_name: practiceData.practice_name,
  has_gmail_credentials: !!practiceData.gmail_credential_id
});

// For unknown practices, we can still process SMS through centralized gateway
// But email will fail if no Gmail credentials are mapped

const automations = practiceData.automations || [];
const smsAutomations = automations.filter(a => a.sms_enabled);
const emailAutomations = automations.filter(a => a.email_enabled);

const outputs = [];

// Process SMS through centralized gateway
if (smsAutomations.length > 0) {
  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'SMS',
      automations: smsAutomations,
      is_unknown_practice: true
    }
  });
}

// For emails, mark as failed if no credentials
if (emailAutomations.length > 0 && !practiceData.gmail_credential_id) {
  const failedEmails = emailAutomations.map(automation => ({
    id: automation.queue_id,
    status: 'failed',
    error_message: 'No Gmail credentials configured for this practice'
  }));

  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'FAILED_EMAIL',
      failed_items: failedEmails
    }
  });
}

if (outputs.length === 0) {
  outputs.push({
    json: {
      practice_id: practiceData.practice_id,
      practice_name: practiceData.practice_name,
      type: 'NONE',
      automations: []
    }
  });
}

return outputs;

