const results = $input.all();
const processedItems = [];

results.forEach(result => {
  if (result.json.success && result.json.results) {
    // SMS batch result from centralized gateway
    result.json.results.forEach(smsResult => {
      if (smsResult.success) {
        processedItems.push({
          id: smsResult.automation_id || smsResult.metadata?.queue_id,
          type: 'SMS',
          practice_id: result.json.practice_id || smsResult.practice_id,
          status: 'completed'
        });
      }
    });
  } else if (result.json.automations) {
    // Fallback for batch processing
    result.json.automations.forEach(automation => {
      processedItems.push({
        id: automation.queue_id || automation.id,
        type: 'SMS',
        practice_id: result.json.practice_id,
        status: 'completed'
      });
    });
  } else if (result.json.failed_items) {
    // Failed emails
    result.json.failed_items.forEach(item => {
      processedItems.push(item);
    });
  }
});

return processedItems.map(item => ({ json: item }));

// Prepare status updates
const allItems = $input.all();
const updates = [];

allItems.forEach(item => {
  if (item.json.id) {
    updates.push({
      id: item.json.id,
      status: item.json.status || 'completed',
      processed_at: new Date().toISOString(),
      error_message: item.json.error_message || null
    });
  }
});

console.log(`Updating ${updates.length} automation statuses`);
return updates.map(update => ({ json: update }));
